'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import EnrollmentForm from '@/components/app/enrollment-form';
import type { Locale } from '@/lib/i18n-config';
import { LanguageSelector } from '@/components/app/language-selector';

// This is a simplified approach. In a real app, you'd use a more robust auth system.
const isAuthenticated = () => {
  if (typeof window === 'undefined') return false;
  return localStorage.getItem('is_authenticated') === 'true';
};

export default function HomeClient({
  lang,
  dictionary,
}: {
  lang: Locale;
  dictionary: any;
}) {
  const router = useRouter();
  const [isClient, setIsClient] = useState(false);

  useEffect(() => {
    setIsClient(true);
    if (!isAuthenticated()) {
      // Redirect to the new, non-localized login page
      router.replace(`/login`);
    }
  }, [router]);

  if (!isClient || !isAuthenticated()) {
    // You can add a loading spinner here
    return null;
  }

  return (
    <main className="flex min-h-screen flex-col items-center bg-background py-12 px-4 sm:px-6 lg:px-8">
      <div className="w-full max-w-5xl space-y-8">
        <header className="text-center relative">
          <LanguageSelector
            lang={lang}
            dictionary={dictionary.languageSelector}
          />
          <h1 className="font-headline text-4xl font-bold tracking-tight text-foreground sm:text-5xl md:text-6xl">
            {dictionary.page.title}
          </h1>
          <p className="mt-4 font-body text-lg text-muted-foreground">
            {dictionary.page.description}
          </p>
        </header>
        <EnrollmentForm dictionary={dictionary.form} lang={lang} />
      </div>
    </main>
  );
}
